record Rule<T>(String name, int salience, Predicate<T> when, Consumer<T> then) {}

List<Rule<Order>> rules = List.of(
    new Rule<>("volume-discount", 10, o -> o.units() > 100, o -> o.applyDiscount(0.10)),
    new Rule<>("vip-shipping",     5, Order::isVip,         o -> o.setFreeShipping(true)));

rules.stream()
     .filter(r -> r.when().test(order))
     .sorted(Comparator.comparingInt(Rule::salience).reversed())
     .forEach(r -> r.then().accept(order));
